challenges.solution:
class Stopwatch {
  constructor() {
    this.elapsed = 0
    this.lastLap = 0
    this.laps = []
  }
  tick(seconds) {
    this.elapsed += seconds
  }
  lap() {
    this.laps.push(this.elapsed - this.lastLap)
    this.lastLap = this.elapsed
  }
  fastest() {
    return this.laps.length === 0 ? null : Math.min(...this.laps)
  }
}

class Queue {
  constructor() {
    this.items = []
  }
  enqueue(x) {
    this.items.push(x)
    return this
  }
  dequeue() {
    return this.items.shift()
  }
  peek() {
    return this.items[0]
  }
  size() {
    return this.items.length
  }
}

