  stock(product, qty) {
    if (!this.#items.has(product.name)) this.#items.set(product.name, { product, qty: 0 })
    this.#items.get(product.name).qty += qty
    return this
  }
  sell(name, qty) {
    const entry = this.#items.get(name)
    if (!entry || entry.qty < qty) throw new Error(`Not enough ${name}`)
    entry.qty -= qty
  }
  get value() {
    let total = 0
    for (const { product, qty } of this.#items.values()) total += product.price * qty
    return total
  }
}

class EventBus {
  #listeners = new Map()
  on(name, fn) {
    const list = this.#listeners.get(name) ?? []
    list.push(fn)
    this.#listeners.set(name, list)
  }
  off(name, fn) {
    const list = this.#listeners.get(name) ?? []
    this.#listeners.set(name, list.filter((f) => f !== fn))
  }
  emit(name, data) {
    const list = this.#listeners.get(name) ?? []
    for (const fn of list) fn(data)
    return list.length
  }
}

