class Library {
  constructor() {
    this.books = []
    this.members = []
  }
  findBook(title) {
    return this.books.find((b) => b.title === title)
  }
  findMember(name) {
    return this.members.find((m) => m.name === name)
  }
  lend(title, name) {
    this.findBook(title).borrower = name
    this.findMember(name).books.push(title)
  }
  giveBack(title, name) {
    const book = this.findBook(title)
    const member = this.findMember(name)
    if (!book || !member || book.borrower !== name) throw new Error(`${name} doesn't have ${title}`)
    book.borrower = null
    member.books = member.books.filter((t) => t !== title)
  }
}

