  }
  available() {
    return this.books
      .filter((b) => b.borrower === null)
      .map((b) => b.title)
      .toSorted((a, b) => a.localeCompare(b))
  }
  onLoan() {
    return this.books
      .filter((b) => b.borrower !== null)
      .toSorted((a, b) => a.title.localeCompare(b.title))
      .map((b) => `${b.title}: ${b.borrower}`)
  }
}

